import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { supabase } from '../lib/supabase';
import { DollarSign, ShoppingCart, Package, TrendingUp, Clock, Users, BarChart3, Receipt, RotateCcw, Percent, CheckCircle, AlertTriangle, Shield, Tag } from 'lucide-react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

const PRICING = [
  { minStores: 1, maxStores: 1, monthly: 150, label: '1 Store' },
  { minStores: 2, maxStores: 2, monthly: 250, label: '2 Stores' },
  { minStores: 3, maxStores: 3, monthly: 580, label: '3 Stores' },
];

export default function Dashboard() {
  const { staff, subscriptionStatus, trialDaysLeft, isLocked, availableStores, storeId } = useAuth();
  const navigate = useNavigate();

  const storeCount = availableStores?.length || 0;
  const plan = PRICING.find(p => storeCount >= p.minStores && storeCount <= p.maxStores);

  const [expiringProducts, setExpiringProducts] = useState([]);
  const [allDiscounts, setAllDiscounts] = useState([]);   // active discount rules

  // Fetch real expiring products and active discounts
  useEffect(() => {
    if (!storeId) return;
    const fetchData = async () => {
      try {
        const today = new Date().toISOString().split('T')[0];

        // Fetch expiring products (within 7 days)
        const { data: productsData, error: productsError } = await supabase
          .from('products')
          .select('id, name, expiry_date, discount_percent, unit_price')
          .eq('store_id', storeId)
          .eq('is_active', true)
          .not('expiry_date', 'is', null)
          .lte('expiry_date', new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString())
          .gte('expiry_date', new Date().toISOString())
          .order('expiry_date');

        // Fetch active discount rules
        const { data: rulesData, error: rulesError } = await supabase
          .from('discount_rules')
          .select('*')
          .eq('store_id', storeId)
          .eq('is_active', true)
          .or(`start_date.lte.${today},start_date.is.null`)
          .or(`end_date.gte.${today},end_date.is.null`);

        const rules = rulesData || [];
        setAllDiscounts(rules);

        if (productsData && !productsError) {
          // Enrich each product with best applicable discount rule
          const enriched = productsData.map(product => {
            const applicableRules = rules.filter(r =>
              !r.product_id || r.product_id === product.id
            );
            let bestRule = null;
            if (applicableRules.length > 0) {
              bestRule = applicableRules.reduce((best, r) => {
                const currentValue = r.type === 'percentage' ? r.value : r.value;
                const bestValue = best.type === 'percentage' ? best.value : best.value;
                if (r.type === 'percentage' && best.type !== 'percentage') return r;
                if (r.type === 'fixed' && best.type === 'percentage') return best;
                return currentValue > bestValue ? r : best;
              });
            }
            const daysLeft = Math.ceil((new Date(product.expiry_date) - new Date()) / (1000 * 60 * 60 * 24));
            return {
              ...product,
              daysLeft,
              ruleDiscount: bestRule ? {
                type: bestRule.type,
                value: bestRule.value,
                name: bestRule.name,
              } : null,
            };
          });
          setExpiringProducts(enriched);
        } else {
          // Fallback dummy data if no products or error (keep existing demo)
          setExpiringProducts([
            { id: 'dummy1', name: 'Fresh Milk 1L', expiry_date: '2026-05-02', daysLeft: 6, discount_percent: 0, ruleDiscount: null },
            { id: 'dummy2', name: 'White Bread', expiry_date: '2026-04-30', daysLeft: 4, discount_percent: 0, ruleDiscount: null },
            { id: 'dummy3', name: 'Greek Yogurt', expiry_date: '2026-04-28', daysLeft: 2, discount_percent: 0, ruleDiscount: null },
          ]);
        }
      } catch (e) {
        console.error('Dashboard data fetch error:', e);
        setExpiringProducts([]);
      }
    };
    fetchData();
  }, [storeId]);

  const salesData = [
    { day: 'Mon', sales: 1240 },
    { day: 'Tue', sales: 1890 },
    { day: 'Wed', sales: 980 },
    { day: 'Thu', sales: 2340 },
    { day: 'Fri', sales: 3120 },
    { day: 'Sat', sales: 2890 },
    { day: 'Sun', sales: 1560 },
  ];

  const handleAddDiscount = (product) => {
    navigate(`/app/discounts?productId=${product.id}&productName=${encodeURIComponent(product.name)}`);
  };

  return (
    <div className="p-4 sm:p-6 max-w-screen-2xl mx-auto">
      {/* Current Package Card */}
      <div className="mb-6 bg-white rounded-3xl p-6 shadow-lg border border-gray-100">
        <div className="flex items-center gap-3 mb-4">
          <Shield className="w-7 h-7 text-green-600" />
          <h2 className="text-2xl font-bold text-gray-800">Current Package</h2>
        </div>

        {plan ? (
          <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
            <div>
              <p className="text-3xl font-bold text-gray-900">{plan.label}</p>
              <p className="text-lg text-green-700 font-medium mt-1">
                ZMW {plan.monthly} <span className="text-gray-500 text-sm">/ month</span>
              </p>
            </div>

            <div className="flex items-center gap-4">
              <div className="flex items-center gap-2">
                {subscriptionStatus === 'active' && (
                  <>
                    <CheckCircle className="text-green-600" size={24} />
                    <span className="text-lg font-semibold text-green-700">Active</span>
                  </>
                )}
                {subscriptionStatus === 'trialing' && (
                  <>
                    <Clock className="text-blue-600" size={24} />
                    <span className="text-lg font-semibold text-blue-700">
                      Trial — {trialDaysLeft > 0 ? `${trialDaysLeft} day${trialDaysLeft > 1 ? 's' : ''} left` : 'Ended'}
                    </span>
                  </>
                )}
                {subscriptionStatus === 'expired' && (
                  <>
                    <AlertTriangle className="text-red-600" size={24} />
                    <span className="text-lg font-semibold text-red-700">Expired</span>
                  </>
                )}
                {subscriptionStatus === 'pending' && (
                  <>
                    <Clock className="text-yellow-600" size={24} />
                    <span className="text-lg font-semibold text-yellow-700">Pending</span>
                  </>
                )}
              </div>

              <button
                onClick={() => navigate('/app/settings')}
                className="bg-green-600 text-white px-6 py-3 rounded-xl font-semibold hover:bg-green-700 whitespace-nowrap"
              >
                {subscriptionStatus === 'active' ? 'Renew / Upgrade' : 'Subscribe Now'}
              </button>
            </div>
          </div>
        ) : (
          <p className="text-gray-500">No store configured.</p>
        )}

        {isLocked && (
          <div className="mt-4 p-3 bg-red-50 border border-red-200 rounded-xl flex items-center gap-2">
            <AlertTriangle className="text-red-600" size={20} />
            <span className="font-medium text-red-700">Access restricted — subscription required.</span>
          </div>
        )}
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-2 md:grid-cols-4 gap-4 sm:gap-6 mb-8">
        <div className="bg-white rounded-3xl p-6 shadow">
          <div className="flex justify-between">
            <div>
              <p className="text-xs sm:text-sm text-gray-500">Today's Sales</p>
              <p className="text-2xl sm:text-4xl font-bold text-green-600">K 8,450</p>
            </div>
            <DollarSign className="w-10 h-10 text-green-600" />
          </div>
        </div>
        <div className="bg-white rounded-3xl p-6 shadow">
          <div className="flex justify-between">
            <div>
              <p className="text-xs sm:text-sm text-gray-500">This Month</p>
              <p className="text-2xl sm:text-4xl font-bold">K 124,800</p>
            </div>
            <TrendingUp className="w-10 h-10 text-blue-600" />
          </div>
        </div>
        <div className="bg-white rounded-3xl p-6 shadow">
          <div className="flex justify-between">
            <div>
              <p className="text-xs sm:text-sm text-gray-500">Transactions</p>
              <p className="text-2xl sm:text-4xl font-bold">67</p>
            </div>
            <ShoppingCart className="w-10 h-10 text-purple-600" />
          </div>
        </div>
        <div className="bg-white rounded-3xl p-6 shadow">
          <div className="flex justify-between">
            <div>
              <p className="text-xs sm:text-sm text-gray-500">Active Lay By</p>
              <p className="text-2xl sm:text-4xl font-bold">12</p>
            </div>
            <Package className="w-10 h-10 text-orange-600" />
          </div>
        </div>
      </div>

      {/* Quick Access Buttons */}
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4 mb-8">
        <button onClick={() => navigate('/app/pos')} className="bg-green-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2 hover:bg-green-700">
          <ShoppingCart className="w-8 h-8" />
          <span className="font-medium">POS</span>
        </button>
        <button onClick={() => navigate('/app/inventory')} className="bg-blue-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2 hover:bg-blue-700">
          <Package className="w-8 h-8" />
          <span className="font-medium">Inventory</span>
        </button>
        <button onClick={() => navigate('/app/employees')} className="bg-purple-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2 hover:bg-purple-700">
          <Users className="w-8 h-8" />
          <span className="font-medium">Employees</span>
        </button>
        <button onClick={() => navigate('/app/discounts')} className="bg-amber-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2 hover:bg-amber-700">
          <Percent className="w-8 h-8" />
          <span className="font-medium">Discounts</span>
        </button>
        <button onClick={() => navigate('/app/layby')} className="bg-orange-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2 hover:bg-orange-700">
          <Package className="w-8 h-8" />
          <span className="font-medium">Lay By</span>
        </button>
        <button onClick={() => navigate('/app/sales')} className="bg-cyan-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2 hover:bg-cyan-700">
          <Receipt className="w-8 h-8" />
          <span className="font-medium">Sales</span>
        </button>
        <button onClick={() => navigate('/app/reports')} className="bg-violet-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2 hover:bg-violet-700">
          <BarChart3 className="w-8 h-8" />
          <span className="font-medium">Reports</span>
        </button>
        <button onClick={() => navigate('/app/returns')} className="bg-red-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2 hover:bg-red-700">
          <RotateCcw className="w-8 h-8" />
          <span className="font-medium">Returns</span>
        </button>
      </div>

      {/* Expiring Products with Discount Badges */}
      <div className="bg-white rounded-3xl p-6 shadow mb-8">
        <div className="flex items-center gap-3 mb-4">
          <Clock className="w-6 h-6 text-red-500" />
          <h2 className="font-semibold">Products Expiring Soon</h2>
        </div>
        {expiringProducts.length === 0 ? (
          <p className="text-gray-500 text-sm py-4">No products expiring within 7 days.</p>
        ) : (
          <div className="space-y-4">
            {expiringProducts.map(product => {
              const hasOwnDiscount = product.discount_percent > 0;
              const ruleDiscount = product.ruleDiscount;
              return (
                <div key={product.id} className="flex items-center justify-between py-2 border-b last:border-0">
                  <div className="flex items-center gap-2">
                    <p className="font-medium">{product.name}</p>
                    {/* Show rule discount badge (blue) */}
                    {ruleDiscount && (
                      <span className="inline-flex items-center gap-0.5 px-2 py-0.5 text-xs font-bold bg-blue-100 text-blue-700 rounded-full">
                        <Tag size={10} />
                        {ruleDiscount.type === 'percentage' ? `-${ruleDiscount.value}%` : `-K${ruleDiscount.value}`}
                      </span>
                    )}
                    {/* Show own discount badge (red) only if no rule discount or alongside */}
                    {hasOwnDiscount && !ruleDiscount && (
                      <span className="inline-flex items-center gap-0.5 px-2 py-0.5 text-xs font-bold bg-red-100 text-red-700 rounded-full">
                        <Tag size={10} /> {product.discount_percent}%
                      </span>
                    )}
                    <p className="text-xs text-gray-500 ml-2">Expires {new Date(product.expiry_date).toLocaleDateString()}</p>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className={`inline-block px-3 py-1 text-xs font-medium rounded-full ${product.daysLeft <= 2 ? 'bg-red-100 text-red-700' : product.daysLeft <= 5 ? 'bg-yellow-100 text-yellow-700' : 'bg-gray-100 text-gray-700'}`}>
                      {product.daysLeft} days
                    </span>
                    <button onClick={() => handleAddDiscount(product)} className="ml-2 text-xs bg-green-600 text-white px-4 py-2 rounded-xl">
                      Add Discount
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Sales Trend */}
      <div className="bg-white rounded-3xl p-6 shadow">
        <h2 className="text-xl font-semibold mb-4">Sales Trend (Last 7 Days)</h2>
        <ResponsiveContainer width="100%" height={320}>
          <LineChart data={salesData}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="day" />
            <YAxis />
            <Tooltip formatter={(value) => `K ${value}`} />
            <Line type="monotone" dataKey="sales" stroke="#10b981" strokeWidth={4} />
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}
